 row['v2CentroidFit_m']=row.pop('candidate_m');row['v2Residual_m']=row.pop('candidateResidual_m');row['candidate_m']=mapped[i].tolist();row['candidateResidual_m']=float(errors[i]);row['candidateMinusAorticOnly_m']=(mapped[i]-z['guide_aortic_only_m'][i]).tolist();row['guideUse']='Coarse regional guide only; zero residual is not an anatomical objective. One sequential half-residual correction was applied.'
